# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: enforces "Rule Exceptions" in .agents/agents.md: code that breaks a rule of the
# repo's AI instructions must carry `ds::exception: <rule> (approved <date>): <why>`. Today:
# every cache (Caching Policy) is tagged, so no cache lands without the user's review.
# Usage: uv run pytest tests/test_rule_exceptions.py
# ---------------------------------------------------------------------------
from __future__ import annotations

import re
from pathlib import Path

import pytest

REPO = Path(__file__).resolve().parents[1]
SCANNED = ("pkgs", "scripts", "experimental", "tools")
SKIPPED = {".venv", "node_modules", ".web", "__pycache__"}
# @cache, @functools.cache, @lru_cache(...), @cached_property, and functools.cache(f) calls
CACHE = re.compile(r"^\s*@(?:functools\.)?(?:cache|lru_cache|cached_property)\b|\b(?:functools\.)?(?:lru_)?cache\(\w")
EXCEPTION = re.compile(r"ds::exception: (?P<rule>[\w-]+) \(approved (?P<date>\d{4}-\d{2}-\d{2})\): \S")
RULES = {"caching"}  # the rule slugs listed in .agents/agents.md "Rule Exceptions"
LOOK_BACK = 4  # lines above a decorator the tag may start on (a wrapped tag, other decorators)


def _python_files() -> list[Path]:
    return [
        path
        for folder in SCANNED
        if (REPO / folder).exists()
        for path in (REPO / folder).rglob("*.py")
        if not SKIPPED.intersection(path.parts)
    ]


def test_every_cache_is_an_approved_exception():
    untagged = []
    for path in _python_files():
        lines = path.read_text().splitlines()
        for n, line in enumerate(lines):
            if line.lstrip().startswith("#") or not CACHE.search(line):
                continue
            near = lines[max(0, n - LOOK_BACK) : n + 1]
            if not any("ds::exception: caching" in other for other in near):
                untagged.append(f"{path.relative_to(REPO)}:{n + 1}: {line.strip()}")
    assert untagged == [], " ".join(
        [
            "caches need the user's approval first (Caching Policy, .agents/agents.md); once approved,",
            "tag them `# ds::exception: caching (approved <date>): <why>`:",
            *untagged,
        ]
    )


def test_exception_tags_are_well_formed():
    bad = []
    for path in _python_files():
        for n, line in enumerate(path.read_text().splitlines(), 1):
            if "ds::exception:" not in line:
                continue
            found = EXCEPTION.search(line)
            if found is None or found["rule"] not in RULES:
                bad.append(f"{path.relative_to(REPO)}:{n}: {line.strip()}")
    assert bad == [], f"expected `ds::exception: <{'|'.join(sorted(RULES))}> (approved YYYY-MM-DD): <why>`: {bad}"


@pytest.mark.parametrize(
    ("line", "is_cache"),
    [
        ("@cache", True),
        ("    @cached_property", True),
        ("@functools.lru_cache(maxsize=32)", True),
        ("handler = functools.cache(load)", True),
        ("# @cache in a comment", False),
        ("def cache_key(x):", False),
        ("cached = False", False),
    ],
)
def test_cache_pattern(line, is_cache):
    assert (not line.lstrip().startswith("#") and bool(CACHE.search(line))) is is_cache
